package com.ralosmarker;

import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.Map;

final class RalosHitTracker<T>
{
    private final Map<T, TargetState> targets = new IdentityHashMap<>();

    void expectHits(T target, int firstHitTick, int lastHitTick, int hitCount,
        Integer startingDefence, Integer defenceDrain)
    {
        TargetState state = targets.computeIfAbsent(target,
            ignored -> new TargetState(startingDefence, defenceDrain));
        state.pendingHits += hitCount;
        state.firstHitTick = Math.min(state.firstHitTick, firstHitTick);
        state.lastHitTick = Math.max(state.lastHitTick, lastHitTick);
    }

    boolean recordHit(T target, int tick, boolean blocked)
    {
        TargetState state = targets.get(target);
        if (state == null || state.pendingHits == 0
            || tick < state.firstHitTick || tick > state.lastHitTick)
        {
            return false;
        }

        state.pendingHits--;
        if (!blocked)
        {
            state.marked = true;
            if (state.defence != null && state.defenceDrain != null)
            {
                state.defence = Math.max(0, state.defence - state.defenceDrain);
            }
        }

        if (state.pendingHits == 0)
        {
            state.clearWindow();
            removeIfUnused(target, state);
        }

        return !blocked;
    }

    void onGameTick(int tick)
    {
        Iterator<Map.Entry<T, TargetState>> iterator = targets.entrySet().iterator();
        while (iterator.hasNext())
        {
            TargetState state = iterator.next().getValue();
            if (state.pendingHits > 0 && tick > state.lastHitTick)
            {
                state.pendingHits = 0;
                state.clearWindow();
            }

            if (!state.marked && state.pendingHits == 0)
            {
                iterator.remove();
            }
        }
    }

    void onDespawn(T target)
    {
        targets.remove(target);
    }

    Integer getDefence(T target)
    {
        TargetState state = target == null ? null : targets.get(target);
        return state != null && state.marked ? state.defence : null;
    }

    boolean isMarked(T target)
    {
        TargetState state = target == null ? null : targets.get(target);
        return state != null && state.marked;
    }

    void reset()
    {
        targets.clear();
    }

    private void removeIfUnused(T target, TargetState state)
    {
        if (!state.marked)
        {
            targets.remove(target);
        }
    }

    private static final class TargetState
    {
        private Integer defence;
        private final Integer defenceDrain;
        private int pendingHits;
        private int firstHitTick = Integer.MAX_VALUE;
        private int lastHitTick = Integer.MIN_VALUE;
        private boolean marked;

        private TargetState(Integer defence, Integer defenceDrain)
        {
            this.defence = defence;
            this.defenceDrain = defenceDrain;
        }

        private void clearWindow()
        {
            firstHitTick = Integer.MAX_VALUE;
            lastHitTick = Integer.MIN_VALUE;
        }
    }
}

package com.ralosmarker;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(RalosMarkerConfig.GROUP)
public interface RalosMarkerConfig extends Config
{
    String GROUP = "ralosMarker";

    @ConfigItem(
        keyName = "marker",
        name = "Marker",
        description = "Text shown after the defence-drained shaman's name"
    )
    default String marker()
    {
        return "*";
    }

    @Range(
        min = 1,
        max = 99
    )
    @ConfigItem(
        keyName = "highestHitpoints",
        name = "Highest Hitpoints level",
        description = "Highest base Hitpoints level in the raid; used to calculate scaled shaman stats"
    )
    default int highestHitpoints()
    {
        return 99;
    }

    @ConfigItem(
        keyName = "markerColor",
        name = "Marker colour",
        description = "Colour of the marker in the right-click menu"
    )
    default Color markerColor()
    {
        return Color.CYAN;
    }
}

package com.ralosmarker;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@PluginDescriptor(
    name = "Ralos Marker",
    description = "Marks NPCs hit by Ralos specials and tracks Defence for Chambers of Xeric shamans",
    tags = {"chambers of xeric", "cox", "shaman", "ralos", "chinchompa"}
)
@Slf4j
public class RalosMarkerPlugin extends Plugin
{
    private static final int RALOS_HIT_DELAY = 2;
    private static final int CHARGED_RALOS_HITS = 2;
    private static final int RALOS_DRAIN_DIVISOR = 8;
    private static final int SHAMAN_BASE_DEFENCE = 210;
    private static final int SHAMAN_BASE_MAGIC = 130;
    private static final int MAX_MARKER_LENGTH = 12;

    private final RalosHitTracker<NPC> hitTracker = new RalosHitTracker<>();
    private final ShamanDefenceCalculator defenceCalculator = new ShamanDefenceCalculator();

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private RalosMarkerConfig config;

    @Provides
    RalosMarkerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(RalosMarkerConfig.class);
    }

    @Override
    protected void startUp()
    {
        hitTracker.reset();
    }

    @Override
    protected void shutDown()
    {
        hitTracker.reset();
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event)
    {
        Actor actor = event.getActor();
        if (!(actor instanceof Player)
            || actor.getAnimation() != AnimationID.HUMAN_GLAIVE_RALOS01_CHARGED_SPECIAL)
        {
            return;
        }

        int attackTick = client.getTickCount();
        clientThread.invokeLater(() -> captureRalosTarget((Player) actor, attackTick));
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event)
    {
        Actor actor = event.getActor();
        Hitsplat hitsplat = event.getHitsplat();
        if (!(actor instanceof NPC) || !isRegularDamageHitsplat(hitsplat.getHitsplatType()))
        {
            return;
        }

        NPC npc = (NPC) actor;
        boolean blocked = hitsplat.getHitsplatType() == HitsplatID.BLOCK_ME
            || hitsplat.getHitsplatType() == HitsplatID.BLOCK_OTHER;
        if (hitTracker.recordHit(npc, client.getTickCount(), blocked))
        {
            log.debug("Ralos hit NPC index {}; calculated Defence is {}",
                npc.getIndex(), hitTracker.getDefence(npc));
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        hitTracker.onGameTick(client.getTickCount());
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        MenuEntry menuEntry = event.getMenuEntry();
        NPC npc = menuEntry.getNpc();
        if (!hitTracker.isMarked(npc))
        {
            return;
        }

        String marker = config.marker().replace('\n', ' ').replace('\r', ' ').trim();
        if (marker.isEmpty())
        {
            return;
        }

        if (marker.length() > MAX_MARKER_LENGTH)
        {
            marker = marker.substring(0, MAX_MARKER_LENGTH);
        }

        Integer defence = hitTracker.getDefence(npc);
        String suffix = marker + (defence == null ? "" : defence);
        menuEntry.setTarget(menuEntry.getTarget() + " "
            + ColorUtil.wrapWithColorTag(Text.escapeJagex(suffix), config.markerColor()));
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        hitTracker.onDespawn(event.getNpc());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        GameState gameState = event.getGameState();
        if (gameState == GameState.HOPPING || gameState == GameState.LOGIN_SCREEN)
        {
            hitTracker.reset();
        }
    }

    private void captureRalosTarget(Player player, int attackTick)
    {
        Actor target = player.getInteracting();
        if (!(target instanceof NPC))
        {
            return;
        }

        NPC npc = (NPC) target;
        ShamanDefenceCalculator.ShamanStats stats = isRaidShaman(npc.getId())
            ? getScaledStats(npc)
            : null;
        Integer startingDefence = stats == null ? null : stats.getDefence();
        Integer defenceDrain = stats == null ? null : stats.getMagic() / RALOS_DRAIN_DIVISOR;
        hitTracker.expectHits(npc,
            attackTick + RALOS_HIT_DELAY,
            attackTick + RALOS_HIT_DELAY,
            CHARGED_RALOS_HITS,
            startingDefence,
            defenceDrain);
        log.debug("Tracking Ralos special against NPC index {} with calculated Defence {}",
            npc.getIndex(), startingDefence);
    }

    private ShamanDefenceCalculator.ShamanStats getScaledStats(NPC npc)
    {
        int partySize = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE_SCALED);
        if (partySize < 1)
        {
            partySize = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE);
        }

        boolean challengeMode = client.getVarbitValue(VarbitID.RAIDS_CHALLENGE_MODE) == 1;
        return defenceCalculator.calculate(
            SHAMAN_BASE_DEFENCE,
            SHAMAN_BASE_MAGIC,
            partySize,
            config.highestHitpoints(),
            challengeMode);
    }

    static boolean isRegularDamageHitsplat(int hitsplatType)
    {
        return hitsplatType == HitsplatID.BLOCK_ME
            || hitsplatType == HitsplatID.BLOCK_OTHER
            || hitsplatType == HitsplatID.DAMAGE_ME
            || hitsplatType == HitsplatID.DAMAGE_OTHER
            || hitsplatType == HitsplatID.DAMAGE_ME_CYAN
            || hitsplatType == HitsplatID.DAMAGE_OTHER_CYAN
            || hitsplatType == HitsplatID.DAMAGE_ME_ORANGE
            || hitsplatType == HitsplatID.DAMAGE_OTHER_ORANGE
            || hitsplatType == HitsplatID.DAMAGE_ME_YELLOW
            || hitsplatType == HitsplatID.DAMAGE_OTHER_YELLOW
            || hitsplatType == HitsplatID.DAMAGE_ME_WHITE
            || hitsplatType == HitsplatID.DAMAGE_OTHER_WHITE
            || hitsplatType == HitsplatID.DAMAGE_MAX_ME
            || hitsplatType == HitsplatID.DAMAGE_MAX_ME_CYAN
            || hitsplatType == HitsplatID.DAMAGE_MAX_ME_ORANGE
            || hitsplatType == HitsplatID.DAMAGE_MAX_ME_YELLOW
            || hitsplatType == HitsplatID.DAMAGE_MAX_ME_WHITE
            || hitsplatType == HitsplatID.DAMAGE_ME_POISE
            || hitsplatType == HitsplatID.DAMAGE_OTHER_POISE
            || hitsplatType == HitsplatID.DAMAGE_MAX_ME_POISE;
    }

    static boolean isRaidShaman(int npcId)
    {
        return npcId == NpcID.RAIDS_LIZARDSHAMAN_A || npcId == NpcID.RAIDS_LIZARDSHAMAN_B;
    }
}

package com.ralosmarker;

final class ShamanDefenceCalculator
{
    private static final int MIN_PARTY_SIZE = 1;
    private static final int MAX_PARTY_SIZE = 100;
    private static final int MIN_SCALED_STAT = 50;
    private static final int MAX_OFFENSIVE_STAT = 5_000;
    private static final int MAX_DEFENSIVE_STAT = 20_000;

    ShamanStats calculate(int baseDefence, int baseMagic, int partySize,
        int highestHitpoints, boolean challengeMode)
    {
        int clampedPartySize = clamp(partySize, MIN_PARTY_SIZE, MAX_PARTY_SIZE);
        int partySizeMinusOne = clampedPartySize - 1;
        int clampedHitpoints = clamp(highestHitpoints, 1, 99);
        int statScaler = clamp(55 + 44 * clampedHitpoints / 99, 55, 99);

        int defence = baseDefence * statScaler / 99;
        int magic = baseMagic * statScaler / 99;

        int offensivePercent = 100 + integerSquareRoot(partySizeMinusOne) * 7
            + partySizeMinusOne;
        int defensivePercent = 100 + integerSquareRoot(partySizeMinusOne)
            + partySizeMinusOne * 7 / 10;

        defence = defence * defensivePercent / 100;
        magic = magic * offensivePercent / 100;

        if (challengeMode)
        {
            defence += defence / 2;
            magic += magic / 2;
        }

        return new ShamanStats(
            clamp(defence, MIN_SCALED_STAT, MAX_DEFENSIVE_STAT),
            clamp(magic, MIN_SCALED_STAT, MAX_OFFENSIVE_STAT));
    }

    private static int integerSquareRoot(int value)
    {
        return (int) Math.sqrt(value);
    }

    private static int clamp(int value, int minimum, int maximum)
    {
        return Math.max(minimum, Math.min(value, maximum));
    }

    static final class ShamanStats
    {
        private final int defence;
        private final int magic;

        private ShamanStats(int defence, int magic)
        {
            this.defence = defence;
            this.magic = magic;
        }

        int getDefence()
        {
            return defence;
        }

        int getMagic()
        {
            return magic;
        }
    }
}

package com.ralosmarker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class RalosHitTrackerTest
{
    @Test
    public void tracksSuccessfulHitsAndDefence()
    {
        Object target = new Object();
        RalosHitTracker<Object> tracker = new RalosHitTracker<>();

        tracker.expectHits(target, 41, 44, 2, 342, 38);
        assertTrue(tracker.recordHit(target, 42, false));
        assertFalse(tracker.recordHit(target, 42, true));
        assertEquals(Integer.valueOf(304), tracker.getDefence(target));
    }

    @Test
    public void combinesSpecsAgainstTheSameTarget()
    {
        Object target = new Object();
        RalosHitTracker<Object> tracker = new RalosHitTracker<>();

        tracker.expectHits(target, 41, 44, 2, 342, 38);
        tracker.expectHits(target, 41, 44, 2, 342, 38);
        for (int i = 0; i < 4; i++)
        {
            tracker.recordHit(target, 42, false);
        }

        assertEquals(Integer.valueOf(190), tracker.getDefence(target));
    }

    @Test
    public void clampsDefenceAtZero()
    {
        Object target = new Object();
        RalosHitTracker<Object> tracker = new RalosHitTracker<>();

        tracker.expectHits(target, 41, 44, 10, 342, 38);
        for (int i = 0; i < 10; i++)
        {
            tracker.recordHit(target, 42, false);
        }

        assertEquals(Integer.valueOf(0), tracker.getDefence(target));
    }

    @Test
    public void doesNotMarkWhenBothHitsMiss()
    {
        Object target = new Object();
        RalosHitTracker<Object> tracker = new RalosHitTracker<>();

        tracker.expectHits(target, 41, 44, 2, 210, 16);
        tracker.recordHit(target, 42, true);
        tracker.recordHit(target, 42, true);
        assertNull(tracker.getDefence(target));
    }

    @Test
    public void ignoresHitsFromAnotherTargetOrOutsideWindow()
    {
        Object target = new Object();
        Object otherTarget = new Object();
        RalosHitTracker<Object> tracker = new RalosHitTracker<>();

        tracker.expectHits(target, 41, 44, 2, 210, 16);
        assertFalse(tracker.recordHit(otherTarget, 42, false));
        assertFalse(tracker.recordHit(target, 40, false));
        tracker.onGameTick(45);
        assertNull(tracker.getDefence(target));
    }

    @Test
    public void clearsTargetWhenItDespawns()
    {
        Object target = new Object();
        RalosHitTracker<Object> tracker = new RalosHitTracker<>();

        tracker.expectHits(target, 41, 44, 2, 210, 16);
        tracker.recordHit(target, 42, false);
        tracker.onDespawn(target);
        assertNull(tracker.getDefence(target));
    }

    @Test
    public void marksTargetWhenDefenceIsUnknown()
    {
        Object target = new Object();
        RalosHitTracker<Object> tracker = new RalosHitTracker<>();

        tracker.expectHits(target, 42, 42, 2, null, null);
        tracker.recordHit(target, 42, false);

        assertTrue(tracker.isMarked(target));
        assertNull(tracker.getDefence(target));
    }

    @Test
    public void appliesScaleOneShamanDrainPerHitsplat()
    {
        Object target = new Object();
        RalosHitTracker<Object> tracker = new RalosHitTracker<>();

        tracker.expectHits(target, 42, 42, 2, 210, 16);
        tracker.recordHit(target, 42, false);
        tracker.recordHit(target, 42, false);

        assertEquals(Integer.valueOf(178), tracker.getDefence(target));
    }
}

package com.ralosmarker;

import net.runelite.api.HitsplatID;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RalosMarkerPluginLogicTest
{
    @Test
    public void acceptsAlternateDamageHitsplats()
    {
        assertTrue(RalosMarkerPlugin.isRegularDamageHitsplat(HitsplatID.DAMAGE_ME));
        assertTrue(RalosMarkerPlugin.isRegularDamageHitsplat(HitsplatID.DAMAGE_ME_CYAN));
        assertTrue(RalosMarkerPlugin.isRegularDamageHitsplat(HitsplatID.DAMAGE_OTHER_CYAN));
        assertTrue(RalosMarkerPlugin.isRegularDamageHitsplat(HitsplatID.DAMAGE_MAX_ME));
    }

    @Test
    public void rejectsDamageOverTimeHitsplats()
    {
        assertFalse(RalosMarkerPlugin.isRegularDamageHitsplat(HitsplatID.POISON));
        assertFalse(RalosMarkerPlugin.isRegularDamageHitsplat(HitsplatID.VENOM));
        assertFalse(RalosMarkerPlugin.isRegularDamageHitsplat(HitsplatID.BURN));
    }
}

