package com.ralosmarker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class ShamanDefenceCalculatorTest
{
    private final ShamanDefenceCalculator calculator = new ShamanDefenceCalculator();

    @Test
    public void calculatesSoloMaxedStats()
    {
        ShamanDefenceCalculator.ShamanStats stats = calculator.calculate(210, 130, 1, 99, false);

        assertEquals(210, stats.getDefence());
        assertEquals(130, stats.getMagic());
    }

    @Test
    public void calculatesSevenManMaxedStats()
    {
        ShamanDefenceCalculator.ShamanStats stats = calculator.calculate(210, 130, 7, 99, false);

        assertEquals(222, stats.getDefence());
        assertEquals(156, stats.getMagic());
    }

    @Test
    public void calculatesEightyScaleMaxedStats()
    {
        ShamanDefenceCalculator.ShamanStats stats = calculator.calculate(210, 130, 80, 99, false);

        assertEquals(342, stats.getDefence());
        assertEquals(305, stats.getMagic());
    }

    @Test
    public void appliesChallengeModeScaling()
    {
        ShamanDefenceCalculator.ShamanStats stats = calculator.calculate(210, 130, 1, 99, true);

        assertEquals(315, stats.getDefence());
        assertEquals(195, stats.getMagic());
    }
}
